import {
  getDB
} from './db'


// =========================================================
// FIND OBJECT KEY
//
// HỖ TRỢ:
//
// Id
// ID
// id
// =========================================================

function findObjectKey(
  data,
  key
) {

  if (
    !data ||
    typeof data !== 'object'
  ) {

    return null

  }


  const target =
    String(key || '')
      .toLowerCase()


  return (
    Object.keys(data)
      .find(x => {

        return (
          String(x)
            .toLowerCase()
          ===
          target
        )

      })
    ||
    null
  )

}


// =========================================================
// CLEAN VALUE
//
// GIỮ NGUYÊN:
//
// Date
// number
// boolean
//
// BỎ:
//
// undefined
// function
// __ob__
// =========================================================

function cleanValue(value) {

  if (
    value === undefined
  ) {

    return undefined

  }


  if (
    typeof value === 'function'
  ) {

    return undefined

  }


  if (
    value instanceof Date
  ) {

    return new Date(
      value.getTime()
    )

  }


  if (
    Array.isArray(value)
  ) {

    return value
      .map(x => {

        return cleanValue(x)

      })
      .filter(x => {

        return (
          x !== undefined
        )

      })

  }


  if (
    value &&
    typeof value === 'object'
  ) {

    const result = {}


    Object.keys(value)
      .forEach(key => {

        if (
          key === '__ob__'
        ) {

          return

        }


        const newValue =
          cleanValue(
            value[key]
          )


        if (
          newValue === undefined
        ) {

          return

        }


        result[key] =
          newValue

      })


    return result

  }


  return value

}


// =========================================================
// COMPARE VALUE
// =========================================================

function compareValue(
  a,
  b
) {

  if (
    a === b
  ) {

    return 0

  }


  if (
    a === undefined ||
    a === null
  ) {

    return -1

  }


  if (
    b === undefined ||
    b === null
  ) {

    return 1

  }


  // =======================================================
  // DATE
  // =======================================================

  if (
    a instanceof Date ||
    b instanceof Date
  ) {

    const av =
      a instanceof Date
        ? a.getTime()
        : new Date(a).getTime()


    const bv =
      b instanceof Date
        ? b.getTime()
        : new Date(b).getTime()


    if (
      !Number.isNaN(av) &&
      !Number.isNaN(bv)
    ) {

      if (av < bv) return -1

      if (av > bv) return 1

      return 0

    }

  }


  // =======================================================
  // NUMBER
  // =======================================================

  if (
    typeof a === 'number' &&
    typeof b === 'number'
  ) {

    if (a < b) return -1

    if (a > b) return 1

    return 0

  }


  // =======================================================
  // BOOLEAN
  // =======================================================

  if (
    typeof a === 'boolean' &&
    typeof b === 'boolean'
  ) {

    return (
      Number(a) -
      Number(b)
    )

  }


  // =======================================================
  // STRING
  // =======================================================

  return String(a)
    .localeCompare(
      String(b),
      'vi',
      {
        numeric: true,
        sensitivity: 'base'
      }
    )

}


// =========================================================
// BASE SERVICE INDEXEDDB
//
// CONTRACT GIỐNG ServicesAccess/baseService.js
// =========================================================

export default class baseService {

  constructor(
    table,
    key = 'Id',
    orderBy = 'Id',
    searchFields = [],
    fieldTypes = {}
  ) {

    this.table =
      table


    this.key =
      key


    this.orderBy =
      orderBy


    this.searchFields =
      Array.isArray(searchFields)
        ? searchFields
        : []


    // =====================================================
    // GIỮ CÙNG SIGNATURE VỚI ACCESS
    //
    // INDEXEDDB KHÔNG CẦN NORMALIZE API TYPE
    // NHƯNG VẪN NHẬN fieldTypes
    // =====================================================

    this.fieldTypes =
      fieldTypes &&
      typeof fieldTypes === 'object' &&
      !Array.isArray(fieldTypes)

        ? {
            ...fieldTypes
          }

        : {}

  }


  // =========================================================
  // COUNT
  // =========================================================

  async count() {

    const db =
      await getDB()


    return await db.count(
      this.table
    )

  }


  // =========================================================
  // GET PAGING CURSOR
  //
  // INTERFACE GIỐNG ACCESS:
  //
  // getPagingCursor({
  //   page,
  //   pageSize,
  //   keyword
  // })
  //
  // RETURN:
  //
  // {
  //   items,
  //   total
  // }
  // =========================================================

  async getPagingCursor({
    page = 1,
    pageSize = 10,
    keyword = ''
  } = {}) {

    const db =
      await getDB()


    const tx =
      db.transaction(
        this.table,
        'readonly'
      )


    const store =
      tx.objectStore(
        this.table
      )


    let all =
      await store.getAll()


    // =====================================================
    // SEARCH
    // =====================================================

    const searchKeyword =
      String(
        keyword || ''
      )
        .trim()
        .toLowerCase()


    if (searchKeyword) {

      all = all.filter(item => {

        // =================================================
        // CÓ searchFields
        //
        // CHỈ SEARCH CÁC FIELD ĐƯỢC KHAI BÁO
        // =================================================

        if (
          Array.isArray(
            this.searchFields
          )
          &&
          this.searchFields.length > 0
        ) {

          return this.searchFields
            .some(field => {

              const realField =
                findObjectKey(
                  item,
                  field
                )


              if (!realField) {

                return false

              }


              return String(
                item[realField]
                ??
                ''
              )
                .toLowerCase()
                .includes(
                  searchKeyword
                )

            })

        }


        // =================================================
        // KHÔNG CÓ searchFields
        //
        // TƯƠNG THÍCH CODE IDB CŨ
        //
        // SEARCH TOÀN OBJECT
        // =================================================

        return Object.values(
          item
        )
          .some(value => {

            return String(
              value
              ??
              ''
            )
              .toLowerCase()
              .includes(
                searchKeyword
              )

          })

      })

    }


    // =====================================================
    // SORT
    // =====================================================

    if (
      this.orderBy &&
      String(
        this.orderBy
      ).trim() !== ''
    ) {

      all = all.sort(
        (a, b) => {

          const aKey =
            findObjectKey(
              a,
              this.orderBy
            )


          const bKey =
            findObjectKey(
              b,
              this.orderBy
            )


          const av =
            aKey
              ? a[aKey]
              : undefined


          const bv =
            bKey
              ? b[bKey]
              : undefined


          return compareValue(
            av,
            bv
          )

        }
      )

    }


    // =====================================================
    // TOTAL
    // =====================================================

    const total =
      all.length


    // =====================================================
    // NORMALIZE PAGE
    // =====================================================

    const safePage =
      Math.max(
        1,
        Number(page) || 1
      )


    const safePageSize =
      Math.max(
        1,
        Number(pageSize) || 10
      )


    // =====================================================
    // PAGING
    // =====================================================

    const start =
      (
        safePage - 1
      )
      *
      safePageSize


    const items =
      all.slice(
        start,
        start + safePageSize
      )


    return {

      items,

      total

    }

  }


// =========================================================
// GET PAGE BY FIELD
//
// TƯƠNG THÍCH ServicesAccess/baseService.js
//
// Service.getPageByField({
//   page: 1,
//   pageSize: 3,
//   keyword: '',
//   fieldName: 'HoaDonId',
//   fieldValue: 15
// })
// =========================================================

async getPageByField({
  page = 1,
  pageSize = 10,
  keyword = '',
  fieldName = '',
  fieldValue = null
} = {}) {

  if (
    !fieldName ||
    String(fieldName).trim() === ''
  ) {

    throw new Error(
      'fieldName không được để trống'
    )

  }


  if (
    fieldValue === null ||
    fieldValue === undefined ||
    fieldValue === ''
  ) {

    throw new Error(
      'fieldValue không được để trống'
    )

  }


  const db =
    await getDB()


  const tx =
    db.transaction(
      this.table,
      'readonly'
    )


  const store =
    tx.objectStore(
      this.table
    )


  let all =
    await store.getAll()


  const realFieldName =
    all.length > 0
      ? findObjectKey(
          all[0],
          fieldName
        )
      : String(fieldName).trim()


  // =====================================================
  // FILTER THEO FIELD
  // =====================================================

  all = all.filter(item => {

    const realField =
      findObjectKey(
        item,
        fieldName
      )


    if (!realField) {

      return false

    }


    const itemValue =
      item[realField]


    // ===================================================
    // DATE
    // ===================================================

    if (
      itemValue instanceof Date ||
      fieldValue instanceof Date
    ) {

      const a =
        itemValue instanceof Date
          ? itemValue.getTime()
          : new Date(itemValue).getTime()


      const b =
        fieldValue instanceof Date
          ? fieldValue.getTime()
          : new Date(fieldValue).getTime()


      return (
        !Number.isNaN(a) &&
        !Number.isNaN(b) &&
        a === b
      )

    }


    // Cho phép:
    // 15 === 15
    // '15' khớp 15

    return (
      itemValue === fieldValue ||
      String(itemValue) === String(fieldValue)
    )

  })


  // =====================================================
  // SEARCH
  // =====================================================

  const searchKeyword =
    String(keyword || '')
      .trim()
      .toLowerCase()


  if (searchKeyword) {

    all = all.filter(item => {

      // =================================================
      // CÓ searchFields
      // =================================================

      if (
        Array.isArray(this.searchFields) &&
        this.searchFields.length > 0
      ) {

        return this.searchFields
          .some(field => {

            const realField =
              findObjectKey(
                item,
                field
              )


            if (!realField) {

              return false

            }


            return String(
              item[realField] ?? ''
            )
              .toLowerCase()
              .includes(
                searchKeyword
              )

          })

      }


      // =================================================
      // KHÔNG CÓ searchFields
      // =================================================

      return Object.values(item)
        .some(value => {

          return String(
            value ?? ''
          )
            .toLowerCase()
            .includes(
              searchKeyword
            )

        })

    })

  }


  // =====================================================
  // SORT
  // =====================================================

  if (
    this.orderBy &&
    String(this.orderBy).trim() !== ''
  ) {

    all = all.sort(
      (a, b) => {

        const aKey =
          findObjectKey(
            a,
            this.orderBy
          )


        const bKey =
          findObjectKey(
            b,
            this.orderBy
          )


        const av =
          aKey
            ? a[aKey]
            : undefined


        const bv =
          bKey
            ? b[bKey]
            : undefined


        return compareValue(
          av,
          bv
        )

      }
    )

  }


  // =====================================================
  // TOTAL
  // =====================================================

  const total =
    all.length


  // =====================================================
  // PAGE SIZE
  // =====================================================

  const safePageSize =
    Math.max(
      1,
      Number(pageSize) || 10
    )


  // =====================================================
  // TOTAL PAGES
  // =====================================================

  const totalPages =
    total === 0
      ? 0
      : Math.ceil(
          total / safePageSize
        )


  // =====================================================
  // CURRENT PAGE
  // =====================================================

  let safePage =
    Math.max(
      1,
      Number(page) || 1
    )


  if (
    totalPages > 0 &&
    safePage > totalPages
  ) {

    safePage =
      totalPages

  }


  // =====================================================
  // PAGING
  // =====================================================

  const start =
    (safePage - 1) *
    safePageSize


  const items =
    all.slice(
      start,
      start + safePageSize
    )


  // =====================================================
  // FROM / TO
  // =====================================================

  const from =
    total === 0
      ? 0
      : start + 1


  const to =
    total === 0
      ? 0
      : Math.min(
          start + items.length,
          total
        )


  // =====================================================
  // RETURN
  // =====================================================

  return {

    items,

    total,

    page:
      safePage,

    pageSize:
      safePageSize,

    totalPages,

    from,

    to,

    hasPreviousPage:
      safePage > 1,

    hasNextPage:
      safePage < totalPages,

    fieldName:
      realFieldName || fieldName,

    fieldValue

  }

}


  // =========================================================
  // GET ALL
  // =========================================================

  async getAll() {

    const db =
      await getDB()


    let items =
      await db.getAll(
        this.table
      )


    // =====================================================
    // SORT THEO orderBy
    // =====================================================

    if (
      this.orderBy &&
      String(
        this.orderBy
      ).trim() !== ''
    ) {

      items = items.sort(
        (a, b) => {

          const aKey =
            findObjectKey(
              a,
              this.orderBy
            )


          const bKey =
            findObjectKey(
              b,
              this.orderBy
            )


          const av =
            aKey
              ? a[aKey]
              : undefined


          const bv =
            bKey
              ? b[bKey]
              : undefined


          return compareValue(
            av,
            bv
          )

        }
      )

    }


    return items

  }


  // =========================================================
  // GET BY ID
  // =========================================================

  async getById(id) {

    const db =
      await getDB()


    const tx =
      db.transaction(
        this.table,
        'readonly'
      )


    const store =
      tx.objectStore(
        this.table
      )


    // =====================================================
    // KEY TRÙNG KEY PATH
    // =====================================================

    if (
      String(
        store.keyPath || ''
      ).toLowerCase()
      ===
      String(
        this.key || ''
      ).toLowerCase()
    ) {

      return await store.get(
        id
      )

    }


    // =====================================================
    // CUSTOM KEY
    // =====================================================

    const all =
      await store.getAll()


    return (
      all.find(item => {

        const realKey =
          findObjectKey(
            item,
            this.key
          )


        if (!realKey) {

          return false

        }


        return (
          item[realKey] === id
        )

      })
      ||
      null
    )

  }


  // =========================================================
  // ADD
  //
  // TƯƠNG THÍCH ACCESS:
  //
  // Service.add(data)
  //
  // TỰ BỎ:
  //
  // Id = 0
  // Id = null
  // Id = ''
  // undefined
  // function
  // __ob__
  // =========================================================

  async add(data) {

    if (
      !data ||
      typeof data !== 'object' ||
      Array.isArray(data)
    ) {

      throw new Error(
        'Data add không hợp lệ'
      )

    }


    const db =
      await getDB()


    const body =
      cleanValue(
        data
      )


    const realKey =
      findObjectKey(
        body,
        this.key
      )


    if (realKey) {

      const id =
        body[realKey]


      if (
        id === 0
        ||
        id === null
        ||
        id === ''
        ||
        id === undefined
      ) {

        delete body[realKey]

      }

    }


    const id =
      await db.add(
        this.table,
        body
      )


    return {

      ...body,

      [this.key]: id

    }

  }


  // =========================================================
  // UPDATE
  //
  // TƯƠNG THÍCH ACCESS:
  //
  // Service.update(data)
  // =========================================================

  async update(data) {

    if (
      !data ||
      typeof data !== 'object' ||
      Array.isArray(data)
    ) {

      throw new Error(
        'Data update không hợp lệ'
      )

    }


    const realKey =
      findObjectKey(
        data,
        this.key
      )


    if (!realKey) {

      throw new Error(
        `Không tìm thấy key ${this.key}`
      )

    }


    const id =
      data[realKey]


    if (
      id === undefined ||
      id === null ||
      id === ''
    ) {

      throw new Error(
        `Không tìm thấy giá trị ${this.key}`
      )

    }


    const db =
      await getDB()


    const body =
      cleanValue(
        data
      )


    await db.put(
      this.table,
      body
    )


    return body

  }


  // =========================================================
  // DELETE
  // =========================================================

  async delete(id) {

    const db =
      await getDB()


    await db.delete(
      this.table,
      id
    )


    return true

  }


  // =========================================================
  // CLEAR
  // =========================================================

  async clear() {

    const db =
      await getDB()


    await db.clear(
      this.table
    )


    return true

  }


  // =========================================================
  // WHERE
  // =========================================================

  async where(predicate) {

    if (
      typeof predicate !== 'function'
    ) {

      throw new Error(
        'predicate phải là function'
      )

    }


    const all =
      await this.getAll()


    return all.filter(
      predicate
    )

  }

}


// =========================================================
// CREATE SERVICE
//
// CÙNG SIGNATURE ServicesAccess/baseService.js
//
// CODE CŨ:
//
// createService('Ban')
//
// VẪN CHẠY
//
// CODE MỚI:
//
// createService(
//   'Ban',
//   'Id',
//   'Id',
//   ['Ten'],
//   {
//     Id: 'int',
//     Tien: 'money',
//     NgayMua: 'datetime'
//   }
// )
// =========================================================

export function createService(
  table,
  key = 'Id',
  orderBy = 'Id',
  searchFields = [],
  fieldTypes = {}
) {

  return new baseService(
    table,
    key,
    orderBy,
    searchFields,
    fieldTypes
  )

}