<template>
  <div class="container-fluid py-3 hoa-don-page">
    <b-card no-body class="shadow-sm">
      <!-- Header -->
      <div class="card-header bg-primary text-white">
        <div class="d-flex justify-content-between align-items-center flex-wrap">
          <h5 class="mb-0">
            <b-icon-file-text class="mr-2"></b-icon-file-text>
            Hóa đơn
          </h5>

          <b-button
            size="sm"
            variant="light"
            :disabled="saving"
            @click="onAdd"
          >
            <b-icon-plus class="mr-1"></b-icon-plus>
            Thêm
          </b-button>
        </div>
      </div>

      <b-card-body>
        <!-- Search -->
        <div class="row mb-3">
          <div class="col-md-6 col-lg-5">
            <b-input-group size="sm">
              <b-form-input
                v-model.trim="keyword"
                placeholder="Tìm theo Khách hàng..."
                @keyup.enter="onSearch"
              />

              <b-input-group-append>
                <b-button
                  variant="primary"
                  @click="onSearch"
                >
                  <b-icon-search class="mr-1"></b-icon-search>
                  Tìm
                </b-button>

                <b-button
                  variant="outline-secondary"
                  @click="onClearSearch"
                >
                  <b-icon-x></b-icon-x>
                </b-button>
              </b-input-group-append>
            </b-input-group>
          </div>
        </div>

        <!-- Table -->
        <b-table
          ref="table"
          :items="myProvider"
          :fields="fields"
          :current-page="page"
          :per-page="pageSize"
          :busy.sync="busy"
          primary-key="Id"
          bordered
          striped
          hover
          small
          responsive
          show-empty
          empty-text="Không có dữ liệu"
          busy-text="Đang tải..."
        >
          <template #cell(stt)="data">
            {{ ((page - 1) * pageSize) + data.index + 1 }}
          </template>

          <template #cell(Ngay)="data">
            {{ formatDate(data.item.Ngay) }}
          </template>

          <template #cell(actions)="data">
            <div class="text-nowrap">
              <b-button
                size="sm"
                variant="warning"
                class="mr-1"
                title="Sửa"
                @click="onEdit(data.item)"
              >
                <b-icon-pencil></b-icon-pencil>
              </b-button>

              <b-button
                size="sm"
                variant="danger"
                title="Xóa"
                @click="onDelete(data.item)"
              >
                <b-icon-trash></b-icon-trash>
              </b-button>
            </div>
          </template>
        </b-table>

        <!-- Footer paging -->
        <div class="row align-items-center mt-2">
          <div class="col-md-4 mb-2 mb-md-0">
            <div class="d-flex align-items-center">
              <span class="mr-2">Số dòng:</span>

              <b-form-select
                v-model="pageSize"
                :options="pageSizeOptions"
                size="sm"
                style="width: 90px"
              />
            </div>
          </div>

          <div class="col-md-4 text-center mb-2 mb-md-0">
            <small class="text-muted">
              Tổng: <strong>{{ totalRows }}</strong> dòng
            </small>
          </div>

          <div class="col-md-4">
            <b-pagination
              v-model="page"
              :total-rows="totalRows"
              :per-page="pageSize"
              align="right"
              size="sm"
              class="mb-0"
            />
          </div>
        </div>
      </b-card-body>
    </b-card>

    <!-- Modal Add/Edit -->
    <b-modal
      v-model="showModal"
      :title="isEdit ? 'Sửa hóa đơn' : 'Thêm hóa đơn'"
      hide-footer
      no-close-on-backdrop
      @hidden="resetForm"
    >
      <b-form @submit.prevent="onSave">
        <!-- Id -->
        <b-form-group
          v-if="isEdit"
          label="Id"
          label-for="txtId"
        >
          <b-form-input
            id="txtId"
            v-model="form.Id"
            disabled
          />
        </b-form-group>

        <!-- KhachId -->
        <b-form-group
          label="Khách hàng"
          label-for="txtKhachId"
          label-class="font-weight-bold"
        >
          <b-form-input
            id="txtKhachId"
            v-model.trim="form.KhachId"
            placeholder="Nhập KhachId"
            :state="khachIdState"
            autocomplete="off"
          />

          <b-form-invalid-feedback>
            Vui lòng nhập KhachId.
          </b-form-invalid-feedback>
        </b-form-group>

        <!-- Ngay -->
        <b-form-group
          label="Ngày"
          label-for="txtNgay"
          label-class="font-weight-bold"
        >
          <b-form-input
            id="txtNgay"
            v-model="form.Ngay"
            type="date"
          />
        </b-form-group>

        <hr />

        <div class="text-right">
          <b-button
            variant="secondary"
            class="mr-2"
            :disabled="saving"
            @click="showModal = false"
          >
            Hủy
          </b-button>

          <b-button
            type="submit"
            variant="primary"
            :disabled="saving"
          >
            <b-spinner
              v-if="saving"
              small
              class="mr-1"
            />

            <b-icon-check-circle
              v-else
              class="mr-1"
            ></b-icon-check-circle>

            {{ saving ? 'Đang lưu...' : 'Lưu' }}
          </b-button>
        </div>
      </b-form>
    </b-modal>
  </div>
</template>

<script>
import HoaDonService from '@/db_services/HoaDonService'

export default {
  name: 'HoaDonView',

  data() {
    return {
      keyword: '',

      page: 1,
      pageSize: 10,
      totalRows: 0,

      pageSizeOptions: [
        { value: 5, text: '5' },
        { value: 10, text: '10' },
        { value: 20, text: '20' },
        { value: 50, text: '50' },
        { value: 100, text: '100' }
      ],

      busy: false,
      saving: false,

      showModal: false,
      isEdit: false,
      submitted: false,

      form: this.newItem(),

      fields: [
        {
          key: 'stt',
          label: '#',
          class: 'text-center',
          thStyle: { width: '60px' }
        },
        {
          key: 'Id',
          label: 'Id',
          class: 'text-center',
          thStyle: { width: '90px' }
        },
        {
          key: 'KhachId',
          label: 'Khách hàng'
        },
        {
          key: 'Ngay',
          label: 'Ngày',
          class: 'text-center',
          thStyle: { width: '150px' }
        },
        {
          key: 'actions',
          label: 'Thao tác',
          class: 'text-center',
          thStyle: { width: '110px' }
        }
      ]
    }
  },

  computed: {
    khachIdState() {
      if (!this.submitted) {
        return null
      }

      return String(this.form.KhachId || '').trim().length > 0
    }
  },

  watch: {
    pageSize() {
      this.page = 1
      this.refreshTable()
    }
  },

  methods: {
    newItem() {
      return {
        Id: 0,
        KhachId: '',
        Ngay: this.today()
      }
    },

    today() {
      const d = new Date()
      const year = d.getFullYear()
      const month = String(d.getMonth() + 1).padStart(2, '0')
      const day = String(d.getDate()).padStart(2, '0')

      return `${year}-${month}-${day}`
    },

    async myProvider(ctx) {
      try {
        const res = await HoaDonService.getPagingCursor({
          page: ctx.currentPage || this.page,
          pageSize: ctx.perPage || this.pageSize,
          keyword: this.keyword || ''
        })

        this.totalRows = Number(res && res.total) || 0

        return (res && res.items) || []
      }
      catch (error) {
        console.error('HoaDonService.getPagingCursor error:', error)

        this.totalRows = 0

        this.showError(
          this.getErrorMessage(error, 'Không tải được danh sách hóa đơn.')
        )

        return []
      }
    },

    refreshTable() {
      this.$nextTick(() => {
        if (this.$refs.table) {
          this.$refs.table.refresh()
        }
      })
    },

    onSearch() {
      this.page = 1
      this.refreshTable()
    },

    onClearSearch() {
      this.keyword = ''
      this.page = 1
      this.refreshTable()
    },

    onAdd() {
      this.isEdit = false
      this.submitted = false
      this.form = this.newItem()
      this.showModal = true
    },

    onEdit(item) {
      this.isEdit = true
      this.submitted = false

      this.form = {
        ...item,
        Ngay: this.toDateInput(item.Ngay)
      }

      this.showModal = true
    },

    async onSave() {
      this.submitted = true

      if (!this.khachIdState) {
        return
      }

      this.saving = true

      try {
        const data = {
          ...this.form,
          Id: Number(this.form.Id || 0),
          KhachId: String(this.form.KhachId || '').trim(),
          Ngay: this.form.Ngay || null
        }

        if (this.isEdit) {
          await HoaDonService.update(data)
        }
        else {
          await HoaDonService.add(data)
        }

        this.showModal = false
        this.page = 1
        this.refreshTable()

        this.showSuccess(
          this.isEdit
            ? 'Cập nhật hóa đơn thành công.'
            : 'Thêm hóa đơn thành công.'
        )
      }
      catch (error) {
        console.error('Save HoaDon error:', error)

        this.showError(
          this.getErrorMessage(error, 'Không lưu được hóa đơn.')
        )
      }
      finally {
        this.saving = false
      }
    },

    async onDelete(item) {
      const ok = await this.$bvModal.msgBoxConfirm(
        `Bạn có chắc muốn xóa hóa đơn Id = ${item.Id}?`,
        {
          title: 'Xác nhận xóa',
          size: 'sm',
          buttonSize: 'sm',
          okVariant: 'danger',
          okTitle: 'Xóa',
          cancelTitle: 'Hủy',
          footerClass: 'p-2',
          hideHeaderClose: false,
          centered: true
        }
      )

      if (!ok) {
        return
      }

      try {
        /*
          baseService của project hiện dùng delete().
          Nếu delete() của bạn nhận Id thay vì object,
          đổi dòng dưới thành:
          await HoaDonService.delete(item.Id)
        */
        await HoaDonService.delete(item.Id)

        if (this.page > 1 && this.totalRows - 1 <= (this.page - 1) * this.pageSize) {
          this.page--
        }

        this.refreshTable()
        this.showSuccess('Xóa hóa đơn thành công.')
      }
      catch (error) {
        console.error('Delete HoaDon error:', error)

        this.showError(
          this.getErrorMessage(error, 'Không xóa được hóa đơn.')
        )
      }
    },

    resetForm() {
      this.submitted = false
      this.isEdit = false
      this.form = this.newItem()
    },

    toDateInput(value) {
      if (!value) {
        return ''
      }

      const text = String(value)

      // ISO: 2026-10-02T00:00:00...
      if (/^\d{4}-\d{2}-\d{2}/.test(text)) {
        return text.substring(0, 10)
      }

      const d = new Date(value)

      if (Number.isNaN(d.getTime())) {
        return ''
      }

      const year = d.getFullYear()
      const month = String(d.getMonth() + 1).padStart(2, '0')
      const day = String(d.getDate()).padStart(2, '0')

      return `${year}-${month}-${day}`
    },

    formatDate(value) {
      if (!value) {
        return ''
      }

      const input = this.toDateInput(value)

      if (!input) {
        return String(value)
      }

      const parts = input.split('-')

      if (parts.length !== 3) {
        return input
      }

      return `${parts[2]}/${parts[1]}/${parts[0]}`
    },

    getErrorMessage(error, fallback) {
      if (
        error &&
        error.response &&
        error.response.data
      ) {
        const data = error.response.data

        if (typeof data === 'string') {
          return data
        }

        if (data.message) {
          return data.message
        }

        if (data.error) {
          return data.error
        }
      }

      if (error && error.message) {
        return error.message
      }

      return fallback
    },

    showSuccess(message) {
      this.$bvToast.toast(message, {
        title: 'Thành công',
        variant: 'success',
        solid: true,
        autoHideDelay: 2500
      })
    },

    showError(message) {
      this.$bvToast.toast(message, {
        title: 'Lỗi',
        variant: 'danger',
        solid: true,
        autoHideDelay: 4000
      })
    }
  }
}
</script>

